  1→import { useState, useRef, useEffect } from 'react';
  2→import ReactMarkdown from 'react-markdown';
  3→import remarkGfm from 'remark-gfm';
  4→import { useTranslation } from '../hooks/useTranslation';
  5→import type { ChatMessage, ContentSegment } from '../types';
  6→import { useAgent } from '../hooks/useAgent';
  7→import { InlineQueryResult } from './InlineQueryResult';
  8→import { ChartWidget } from './ChartWidget';
  9→import { UserQuestion } from './UserQuestion';
 10→import './MessageBubble.css';
 11→
 12→/**
 13→ * Strip chart_spec JSON code blocks from answer text.
 14→ * The orchestrator may include the raw chart spec JSON even though the chart
 15→ * is rendered separately. Remove ```json ... ``` blocks containing chart_spec
 16→ * or Plotly trace data so they don't appear as raw text.
 17→ */
 18→function stripChartSpecBlocks(text: string): string {
 19→  return text.replace(/```(?:json)?\s*\n?\s*\{[\s\S]*?"(?:chart_spec|data)"[\s\S]*?\}\s*\n?\s*```/g, '').trim();
 20→}
 21→
 22→function getLastThinkingLine(segments: ContentSegment[], streamingRemainder: string | undefined, t: (key: string) => string): string {
 23→  // Use streaming remainder if available
 24→  if (streamingRemainder?.trim()) {
 25→    const lines = streamingRemainder.trim().split('\n').filter((l) => l.trim());
 26→    const last = lines[lines.length - 1] || '';
 27→    return last.length > 100 ? last.slice(0, 100) + '...' : last;
 28→  }
 29→  // Otherwise use last thinking segment's last line
 30→  for (let i = segments.length - 1; i >= 0; i--) {
 31→    if (segments[i].type === 'thinking' && segments[i].text?.trim()) {
 32→      const lines = segments[i].text!.trim().split('\n').filter((l) => l.trim());
 33→      const last = lines[lines.length - 1] || '';
 34→      return last.length > 100 ? last.slice(0, 100) + '...' : last;
 35→    }
 36→  }
 37→  return t('thinking');
 38→}
 39→
 40→function ThinkingBlock({ segments, streamingRemainder, isThinkingPhase, isAgentStreaming, hasAnswer }: {
 41→  segments: ContentSegment[];
 42→  streamingRemainder?: string;
 43→  isThinkingPhase: boolean;
 44→  isAgentStreaming: boolean;
 45→  hasAnswer: boolean;
 46→}) {
 47→  const { t } = useTranslation();
 48→  // All non-answer, non-chart, non-user_question segments go inside the thinking block
 49→  // When hasAnswer is true, subagent_end text segments are shown here instead of in the answer block
 50→  const thinkingSegments = segments.filter(
 51→    (s) => s.type !== 'answer' && s.type !== 'user_question' && !(s.type === 'tool' && s.toolResult?.chart_spec) && !(s.type === 'subagent_end' && (s.chart_spec || (s.text?.trim() && !hasAnswer)))
 52→  );
 53→  const hasContent = thinkingSegments.some(
 54→    (s) => (s.type === 'thinking' && s.text?.trim()) || (s.type === 'tool' && s.toolResult) || s.type === 'subagent_start' || (s.type === 'subagent_end' && !s.chart_spec && s.text?.trim())
 55→  ) || streamingRemainder?.trim();
 56→
 57→  if (!hasContent) return null;
 58→
 59→  // Show preview only while agent is still working (hidden by CSS when collapsible is open anyway)
 60→  const summary = isAgentStreaming ? getLastThinkingLine(segments, streamingRemainder, t) : '';
 61→
 62→  return (
 63→    <details className="message-bubble__segment message-bubble__segment--thinking message-bubble__collapsible" open={isThinkingPhase || undefined}>
 64→      <summary className="message-bubble__collapsible-summary">
 65→        <span className="message-bubble__segment-label">{t('thinkingLabel')}</span>
 66→        {summary && <span className="message-bubble__collapsible-preview">{summary}</span>}
 67→      </summary>
 68→      <div className="message-bubble__thinking-body">
 69→        {thinkingSegments.map((seg, i) => {
 70→          if (seg.type === 'thinking' && seg.text?.trim()) {
 71→            return (
 72→              <div key={i} className="message-bubble__segment-content">
 73→                <ReactMarkdown remarkPlugins={[remarkGfm]}>{seg.text}</ReactMarkdown>
 74→              </div>
 75→            );
 76→          }
 77→          if (seg.type === 'tool' && seg.toolResult) {
 78→            return (
 79→              <div key={i} className="message-bubble__tool-segment">
 80→                <InlineQueryResult result={seg.toolResult} />
 81→              </div>
 82→            );
 83→          }
 84→          if (seg.type === 'subagent_start') {
 85→            const displayName = seg.subagentName === 'sql-analyst'
 86→              ? t('sqlAnalystWorking')
 87→              : seg.subagentName === 'chart-builder'
 88→              ? t('chartBuilderWorking')
 89→              : `${seg.subagentName} working...`;
 90→            return (
 91→              <div key={i} className="message-bubble__subagent-indicator">
 92→                <span className="message-bubble__subagent-label">{displayName}</span>
 93→              </div>
 94→            );
 95→          }
 96→          if (seg.type === 'subagent_end' && !seg.chart_spec && seg.text?.trim()) {
 97→            return (
 98→              <div key={i} className="message-bubble__segment-content">
 99→                <ReactMarkdown remarkPlugins={[remarkGfm]}>{seg.text}</ReactMarkdown>
100→              </div>
101→            );
102→          }
103→          return null;
104→        })}
105→        {streamingRemainder?.trim() && (
106→          <div className="message-bubble__segment-content">
107→            <ReactMarkdown remarkPlugins={[remarkGfm]}>{streamingRemainder}</ReactMarkdown>
108→          </div>
109→        )}
110→      </div>
111→    </details>
112→  );
113→}
