517→  const deleteMessage = useCallback(
518→    (messageIndex: number) => {
519→      if (isStreaming) return;
520→
521→      // Store remaining messages as history for Langfuse context on next send
522→      setMessages((prev) => {
523→        const remaining = prev.slice(0, messageIndex);
524→        pendingHistoryRef.current = remaining
525→          .filter((m) => m.role === 'user' || m.role === 'assistant')
526→          .map((m) => ({ role: m.role, content: m.content }));
527→        return remaining;
528→      });
529→
530→      // Clear session so next message starts fresh
531→      sessionIdRef.current = null;
532→    },
533→    [isStreaming]
534→  );
535→
536→  const respondToQuestion = useCallback(
537→    async (questionId: string, answers: string[], freeText?: string) => {
538→      // Update the segment to show the user's answer
539→      const segIdx = segmentsRef.current.findIndex(
540→        (s) => s.type === 'user_question' && s.questionData?.questionId === questionId
541→      );
542→      if (segIdx !== -1) {
543→        segmentsRef.current[segIdx] = {
544→          ...segmentsRef.current[segIdx],
545→          userAnswer: answers,
546→          userFreeText: freeText,
547→        };
548→        setMessages((prev) =>
549→          prev.map((m) =>
550→            m.id === assistantIdRef.current
551→              ? { ...m, segments: [...segmentsRef.current] }
552→              : m
553→          )
554→        );
555→      }
556→
557→      // POST to backend
558→      try {
559→        await fetch('/api/chat/respond', {
560→          method: 'POST',
561→          headers: {
562→            'Content-Type': 'application/json',
563→            ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
564→          },
